<?php $this->assign('title', 'Nova cotação'); ?><h1 class="h3 mb-4">Cotação · <?= h($solicitacao->numero) ?></h1><div class="card border-0 shadow-sm"><div class="card-body p-4"><?= $this->Form->create() ?><?= $this->Form->control('fornecedor_id', ['options' => $fornecedores, 'class' => 'form-select']) ?><div class="row g-3"><?php foreach ($solicitacao->solicitacoes_compras_itens as $item): ?><div class="col-md-6"><?= $this->Form->control("precos.{$item->id}", ['label' => "Preço unitário · item {$item->id}", 'type' => 'number', 'step' => '.01', 'min' => 0, 'class' => 'form-control']) ?></div><?php endforeach; ?><div class="col-md-4"><?= $this->Form->control('prazo_entrega', ['class' => 'form-control']) ?></div><div class="col-md-8"><?= $this->Form->control('condicoes_pagamento', ['class' => 'form-control']) ?></div></div><div class="mt-4"><?= $this->Form->button('Registrar cotação', ['class' => 'btn btn-primary']) ?></div><?= $this->Form->end() ?></div></div>
